14	#include "dxa_unit.h"
15	#include "core.h"
16	#include "constants.h"
17	#include "debug.h"
18	
19	using namespace vortex;
20	
21	instr_trace_t* DxaUnit::process(instr_trace_t* trace) {
22	  if (req_out_.full()) {
23	    return nullptr;
24	  }
25	
26	  // 4-lane wgather encoding:
27	  //   Lane 0: rs1=smem_addr, rs2=coord2
28	  //   Lane 1: rs1=meta,      rs2=coord3
29	  //   Lane 2: rs1=coord0,    rs2=coord4
30	  //   Lane 3: rs1=coord1,    rs2=cta_mask
31	  auto& rs1 = trace->src_data[0];
32	  auto& rs2 = trace->src_data[1];
33	
34	  uint64_t smem_addr = static_cast<uint64_t>(rs1.at(0).u);
35	  uint32_t meta      = rs1.at(1).u;
36	  uint32_t coords[5] = {
37	    static_cast<uint32_t>(rs1.at(2).u),
38	    static_cast<uint32_t>(rs1.at(3).u),
39	    static_cast<uint32_t>(rs2.at(0).u),
40	    static_cast<uint32_t>(rs2.at(1).u),
41	    static_cast<uint32_t>(rs2.at(2).u),
42	  };
43	  uint32_t cta_mask  = rs2.at(3).u;
44	  uint32_t desc_slot = meta & 0x0fu;
45	  uint32_t raw_bar   = (meta >> 4) & 0x07ffffffu;
46	
47	  DxaReq req;
48	  req.core      = core_;
49	  req.uuid      = trace->uuid;
50	  req.wid       = trace->wid;
51	  req.desc_slot = desc_slot;
52	  // Keep raw bar_id; multicast offset arithmetic relies on encoded form
53	  // (cta_no in low 8 bits → bar_id + cta_idx targets next CTA's same bar).
54	  // Release call site decodes via bar_decode_id().
55	  req.bar_id    = raw_bar;
56	  req.cta_mask  = cta_mask;
57	  req.smem_addr = smem_addr;
58	  for (int i = 0; i < 5; ++i) req.coords[i] = coords[i];
59	
60	  // Barrier pre-registration is the kernel's responsibility via
61	  // vx_barrier_expect_tx(). The DXA pipeline only emits release events on
62	  // completion; pre-registration happens explicitly per-CTA so multicast
63	  // destinations correctly wait.
64	
65	  req_out_.send(req);
66	  DT(4, "dxa-unit submit: core=" << core_->id() << ", wid=" << trace->wid
67	     << ", slot=" << desc_slot << ", bar=" << raw_bar
68	     << ", cta_mask=0x" << std::hex << cta_mask << std::dec);
69	  return trace;
70	}
