28	using namespace vortex;
29	
30	namespace {
31	
32	// Number of GMEM ports DxaCore exposes to L2 (one arb output per port).
33	constexpr uint32_t kDxaMemPorts = std::min<uint32_t>(VX_CFG_NUM_DXA_CORES, VX_CFG_L2_NUM_REQS);
34	
35	// LMEM "word" granularity for splitting DXA writes. The LocalMem bank
36	// model applies byteen relative to a VX_CFG_MEM_BLOCK_SIZE-aligned address,
37	// so each LineWork's destination must lie within one VX_CFG_MEM_BLOCK_SIZE-aligned
38	// region. mem_block granularity is the byteen-mask scope.
39	constexpr uint32_t kLmemWordSize = VX_CFG_MEM_BLOCK_SIZE;
40	
41	// GMEM line size + mask.
42	constexpr uint32_t kGmemLineSize = VX_CFG_L1_LINE_SIZE;
43	constexpr uint64_t kGmemLineMask = ~uint64_t(VX_CFG_L1_LINE_SIZE - 1);
44	
45	// Cores per cluster.
46	constexpr uint32_t kCoresPerCluster = NUM_SOCKETS * VX_CFG_SOCKET_SIZE;
47	
48	} // namespace
49	
50	// ════════════════════════════════════════════════════════════════════
51	// DxaCore::Impl
52	// ════════════════════════════════════════════════════════════════════
53	
54	class DxaCore::Impl {
55	public:
56	  // ── Descriptor ──────────────────────────────────────────────────────
57	  struct Descriptor {
58	    uint64_t base_addr = 0;
59	    std::array<uint32_t, 5> sizes = {};
60	    std::array<uint32_t, 4> strides = {};
61	    uint32_t meta = 0;
62	    std::array<uint32_t, 5> element_strides = {};
63	    std::array<uint16_t, 5> tile_sizes = {};
64	    uint32_t cfill = 0;
65	    uint32_t smem_stride = 0;
66	  };
67	
68	  // ── Per-line work item produced by addr_gen, consumed by gmem_req ───
69	  // Each entry = ONE GMEM cache-line read. Row-major writes contribute it to a
70	  // single contiguous LMEM word write; a K-major transposing load fans it out
71	  // to `km_num_elems` strided per-element destinations, which smem_wr coalesces
72	  // back into full byte-masked block writes (one read → bank-parallel scatter,
73	  // never re-reading a line per element — TMA-style, matching the RTL addr_gen
74	  // which reads per cache line).
75	  struct LineWork {
76	    uint64_t gmem_cl_addr;     // CL-aligned global address
77	    uint64_t smem_word_addr;   // word-aligned SMEM byte address (element 0)
78	    uint32_t cl_byte_offset;   // start of valid bytes within the CL (element 0)
79	    uint32_t smem_byte_offset; // destination offset within the SMEM word (element 0)
80	    uint32_t valid_length;     // valid bytes per write
81	    uint32_t cfill;            // OOB fill value (lane-replicated)
82	    bool     oob;              // skip GMEM read; use cfill
83	    bool     last;             // last work item of the transfer
84	    uint32_t km_num_elems;     // K-major scatter fan-out (1 = contiguous write)
85	    uint32_t km_lane_stride;   // SMEM byte stride between scattered elements
86	    uint8_t  dest_layout;      // DestLayout (Flat/BlockMajor use tiled_dest_elem)
87	    uint32_t tile_k_row;       // tiled scatter: K-row (dim1 index) for this span
88	    uint32_t tile_n_base;      // tiled scatter: N (dim0) index where the span starts
89	  };
90	
91	  // ── Inflight slot for a GMEM read ──────────────────────────────────
92	  struct InflightSlot {
93	    bool      allocated = false;
94	    bool      rsp_arrived = false;
95	    LineWork  work;            // captured at allocation
96	    std::shared_ptr<mem_block_t> rsp_data;
97	  };
98	
99	  // ── Worker (one per slice) ───────────────────────────────────────────
100	  enum class WState { IDLE, RUNNING };
101	
102	  struct Worker {
103	    WState                  state = WState::IDLE;
104	    uint32_t                worker_id = 0;
105	    DxaReq                  req;
106	    Descriptor              desc;
107	    bool                    is_multicast = false;
108	    std::vector<uint32_t>   cta_indices;
109	    uint32_t                smem_stride = 0;
110	    uint64_t                issue_cycle = 0;
111	
112	    // addr_gen: pre-enumerated work list (one entry per GMEM CL +
113	    // multicast replays handled at smem_wr stage).
114	    std::vector<LineWork>   work_list;
115	    uint32_t                ag_idx = 0;          // next entry to issue (gmem_req)
116	
117	    // gmem_req → rsp_buf → smem_wr inflight bookkeeping.
118	    std::array<InflightSlot, VX_CFG_DXA_MAX_INFLIGHT> inflight;
119	    std::deque<uint32_t>    issued_order;        // tag order, FIFO drain
120	
121	    // smem_wr multicast replay state.
122	    uint32_t                mc_cta_idx = 0;      // 0..cta_indices.size()
123	    uint32_t                km_elem_idx = 0;     // 0..km_num_elems (K-major scatter)
124	    uint32_t                writes_emitted = 0;  // count for perf
125	  };
126	
127	  // ── Constructor ──────────────────────────────────────────────────────
128	  explicit Impl(DxaCore* simobject, MemArbiter* gmem_arb)
129	    : simobject_(simobject)
130	    , gmem_arb_(gmem_arb)
131	    , workers_(VX_CFG_NUM_DXA_CORES)
132	    , cycle_(0)
133	  {
134	    for (uint32_t i = 0; i < VX_CFG_NUM_DXA_CORES; ++i)
135	      workers_[i].worker_id = i;
136	  }
137	
138	  void reset() {
139	    cycle_ = 0;
140	    queue_.clear();
141	    perf_stats_ = DxaCore::PerfStats();
142	    for (auto& w : workers_) {
143	      w.state = WState::IDLE;
144	      w.work_list.clear();
145	      w.cta_indices.clear();
146	      w.issued_order.clear();
147	      for (auto& s : w.inflight) { s.allocated = false; s.rsp_arrived = false; s.rsp_data.reset(); }
148	      w.ag_idx = 0;
149	      w.mc_cta_idx = 0;
150	      w.km_elem_idx = 0;
151	      w.writes_emitted = 0;
152	    }
153	  }
154	
155	  int dcr_write(uint32_t addr, uint32_t value) {
156	    uint32_t slot = VX_DCR_DXA_DESC_SLOT(addr);
157	    uint32_t word = VX_DCR_DXA_DESC_WORD(addr);
158	    auto& d = descriptors_.at(slot);
159	    switch (word) {
160	    case VX_DCR_DXA_DESC_BASE_LO_OFF:   d.base_addr = (d.base_addr & 0xffffffff00000000ull) | value; break;
161	    case VX_DCR_DXA_DESC_BASE_HI_OFF:   d.base_addr = (d.base_addr & 0x00000000ffffffffull) | (uint64_t(value) << 32); break;
162	    case VX_DCR_DXA_DESC_SIZE0_OFF:     d.sizes[0] = value; break;
163	    case VX_DCR_DXA_DESC_SIZE1_OFF:     d.sizes[1] = value; break;
164	    case VX_DCR_DXA_DESC_SIZE2_OFF:     d.sizes[2] = value; break;
165	    case VX_DCR_DXA_DESC_SIZE3_OFF:     d.sizes[3] = value; break;
166	    case VX_DCR_DXA_DESC_SIZE4_OFF:     d.sizes[4] = value; break;
167	    case VX_DCR_DXA_DESC_STRIDE0_OFF:   d.strides[0] = value; break;
168	    case VX_DCR_DXA_DESC_STRIDE1_OFF:   d.strides[1] = value; break;
169	    case VX_DCR_DXA_DESC_STRIDE2_OFF:   d.strides[2] = value; break;
170	    case VX_DCR_DXA_DESC_STRIDE3_OFF:   d.strides[3] = value; break;
171	    case VX_DCR_DXA_DESC_META_OFF:      d.meta = value; break;
172	    case VX_DCR_DXA_DESC_ESTRIDE0_OFF:  d.element_strides[0] = value; break;
173	    case VX_DCR_DXA_DESC_ESTRIDE1_OFF:  d.element_strides[1] = value; break;
174	    case VX_DCR_DXA_DESC_ESTRIDE2_OFF:  d.element_strides[2] = value; break;
175	    case VX_DCR_DXA_DESC_ESTRIDE3_OFF:  d.element_strides[3] = value; break;
176	    case VX_DCR_DXA_DESC_ESTRIDE4_OFF:  d.element_strides[4] = value; break;
177	    case VX_DCR_DXA_DESC_TILESIZE01_OFF:
178	      d.tile_sizes[0] = uint16_t(value & 0xffff);
179	      d.tile_sizes[1] = uint16_t(value >> 16);
180	      break;
181	    case VX_DCR_DXA_DESC_TILESIZE23_OFF:
182	      d.tile_sizes[2] = uint16_t(value & 0xffff);
183	      d.tile_sizes[3] = uint16_t(value >> 16);
184	      break;
185	    case VX_DCR_DXA_DESC_TILESIZE4_OFF: d.tile_sizes[4] = uint16_t(value & 0xffff); break;
186	    case VX_DCR_DXA_DESC_CFILL_OFF:     d.cfill = value; break;
187	    case VX_DCR_DXA_DESC_SMEM_STRIDE_OFF:
188	      // Round up to the LMEM word size so multicast destination addresses
189	      // `issuer_addr + r * smem_stride` stay block-aligned. The LMEM model
190	      // treats requests as block-aligned with a byteen mask; a non-aligned
191	      // stride would truncate the address and land writes in the wrong
192	      // block. The dispatcher applies the same rounding to per-CTA LMEM
193	      // allocations so the host-visible "same offset in receiver LMEM"
194	      // contract holds end-to-end.
195	      d.smem_stride = (value + kLmemWordSize - 1u) & ~uint32_t(kLmemWordSize - 1u);
196	      break;
197	    default: break;
198	    }
199	    return 0;
200	  }
201	
202	  void tick() {
203	    ++cycle_;
204	
205	    // Drain in reverse-pipeline order (smem_wr → rsp_buf → gmem_req →
206	    // addr_gen → setup → req-arb) so each stage's tick reads what its
207	    // upstream produced earlier this cycle, mimicking forward stage flow.
208	
209	    // 1) Drain GMEM responses → mark inflight slots arrived.
210	    // gmem_arb_ already routes responses back to RspOut[worker_id] (its
211	    // input index) and restores the user's tag (the per-worker slot id).
212	    for (uint32_t worker_id = 0; worker_id < workers_.size(); ++worker_id) {
213	      auto& ch = gmem_arb_->RspOut.at(worker_id);
214	      // One response per port per cycle (each worker has its own RspOut port).
215	      if (!ch.empty()) {
216	        auto& rsp = ch.peek();
217	        uint32_t slot_id = uint32_t(rsp.tag) & (VX_CFG_DXA_MAX_INFLIGHT - 1);
218	        auto& w = workers_[worker_id];
219	        if (slot_id < w.inflight.size() && w.inflight[slot_id].allocated) {
220	          w.inflight[slot_id].rsp_arrived = true;
221	          w.inflight[slot_id].rsp_data    = rsp.data;
222	        }
223	        ch.pop();
224	      }
225	    }
226	
227	    // 2) Tick workers (smem_wr drain → gmem_req issue).
228	    for (auto& w : workers_) {
229	      if (w.state == WState::RUNNING) {
230	        tick_worker_smem_wr(w);
231	        tick_worker_gmem_req(w);
232	      }
233	    }
234	
235	    // 3) Dispatch from queue to idle workers.
236	    for (auto& w : workers_) {
237	      if (w.state == WState::IDLE && !queue_.empty())
238	        start_worker(w, queue_.front()), queue_.pop_front();
239	    }
240	
241	    // 4) Drain DxaUnit channels → req queue (round-robin).
242	    drain_req_in();
243	  }
244	
245	  const DxaCore::PerfStats& perf_stats() const { return perf_stats_; }
246	
247	private:
248	  // ── Descriptor helpers ───────────────────────────────────────────────
249	  static uint32_t desc_rank(uint32_t meta) {
250	    uint32_t r = (meta >> DXA_DESC_META_DIM_LSB)
251	                  & ((1u << DXA_DESC_META_DIM_BITS) - 1u);
252	    return (r == 0) ? 1u : std::min(r, 5u);
253	  }
254	
255	  static uint32_t desc_elem_bytes(uint32_t meta) {
256	    uint32_t enc = (meta >> DXA_DESC_META_ELEMSZ_LSB)
257	                    & ((1u << DXA_DESC_META_ELEMSZ_BITS) - 1u);
258	    return 1u << enc;
259	  }
260	
261	  // Destination SMEM layout (2-bit LAYOUT meta field). Mirrors dxa.h::Layout.
262	  enum class DestLayout : uint32_t { RowMajor = 0, KMajor = 1, Flat = 2, BlockMajor = 3 };
263	
264	  static DestLayout desc_layout(uint32_t meta) {
265	    uint32_t v = (meta >> DXA_DESC_META_LAYOUT_LSB)
266	                 & ((1u << DXA_DESC_META_LAYOUT_BITS) - 1u);
267	    return DestLayout(v);
268	  }
269	
270	  // K-major destination layout (TMA style): SMEM addr per element is
271	  // base + i1 * elem_bytes + e0 * tile1 * elem_bytes (instead of the default
272	  // row-major base + i1 * tile0 * elem_bytes + e0 * elem_bytes).
273	  static bool desc_dest_kmajor(uint32_t meta) { return desc_layout(meta) == DestLayout::KMajor; }
274	
275	  // Flat (sparse) / BlockMajor (dense) reuse the K-major SCATTER datapath
276	  // (contiguous GMEM read → permuted SMEM write) with a richer per-element
277	  // destination index. tcN rides ESTRIDE2 (set_tile_geometry).
278	  static bool desc_dest_tiled(uint32_t meta) {
279	    DestLayout l = desc_layout(meta);
280	    return l == DestLayout::Flat || l == DestLayout::BlockMajor;
281	  }
282	
283	  // WGMMA tile geometry conveyed by set_tile_geometry() via ESTRIDE2.
284	  static uint32_t desc_geo_tcn(const Descriptor& d) {
285	    return std::max<uint32_t>(1u, d.element_strides[2]);
286	  }
287	
288	  // SMEM element-index for B element (k = K-row, n = N-col) under the bbuf's
289	  // native layouts. Mirrors vx_tensor.h::b_sp_flat_idx / b_blockmajor_idx
290	  // (tcK == tcN for canonical WGMMA configs; ratio = 32-bit-word / elem).
291	  static uint32_t tiled_dest_elem(DestLayout lay, uint32_t k, uint32_t n,
292	                                  uint32_t ratio, uint32_t tcN, uint32_t n_steps) {
293	    if (lay == DestLayout::Flat) {
294	      uint32_t b_tcK_words = tcN * 2;
295	      uint32_t blk_words   = tcN * b_tcK_words;
296	      uint32_t k_word = k / ratio;
297	      uint32_t elem   = k % ratio;
298	      uint32_t k_blk  = k_word / b_tcK_words;
299	      uint32_t kw_in  = k_word % b_tcK_words;
300	      uint32_t n_blk  = n / tcN;
301	      uint32_t n_in   = n % tcN;
302	      uint32_t word_off = (k_blk * n_steps + n_blk) * blk_words + (kw_in * tcN + n_in);
303	      return word_off * ratio + elem;
304	    }
305	    // BlockMajor (dense): within-block N-outer, K-inner.
306	    uint32_t kw          = tcN * ratio;        // tcK * i_ratio
307	    uint32_t b_blk_elems = kw * tcN;
308	    uint32_t k_blk = k / kw;
309	    uint32_t r_in  = k % kw;
310	    uint32_t n_blk = n / tcN;
311	    uint32_t n_in  = n % tcN;
312	    return (k_blk * n_steps + n_blk) * b_blk_elems + n_in * kw + r_in;
313	  }
314	
315	  // ── Pull from per-core dxa_req_in[] into queue_ (round-robin) ────────
316	  void drain_req_in() {
317	    auto& chs = simobject_->dxa_req_in;
318	    for (uint32_t i = 0; i < chs.size(); ++i) {
319	      uint32_t cid = (rr_req_ + i) % chs.size();
320	      auto& ch = chs.at(cid);
321	      if (ch.empty()) continue;
322	      if (queue_.size() >= VX_CFG_DXA_QUEUE_SIZE) break;
323	      queue_.push_back(ch.peek());
324	      ch.pop();
325	      rr_req_ = (cid + 1) % chs.size();
326	      break;
327	    }
328	  }
329	
330	  // ── Setup: pre-enumerate the work list for this transfer ─────────────
331	  void start_worker(Worker& w, const DxaReq& req) {
332	    w.req = req;
333	    w.issue_cycle = cycle_;
334	    w.work_list.clear();
335	    w.ag_idx = 0;
336	    w.issued_order.clear();
337	    for (auto& s : w.inflight) { s.allocated = false; s.rsp_arrived = false; s.rsp_data.reset(); }
338	    w.mc_cta_idx = 0;
339	    w.km_elem_idx = 0;
340	    w.writes_emitted = 0;
341	
342	    // Multicast setup.
343	    w.is_multicast = (__builtin_popcount(req.cta_mask) > 1);
344	    w.cta_indices.clear();
345	    if (w.is_multicast) {
346	      for (uint32_t i = 0; i < 32; ++i) {
347	        if (req.cta_mask & (1u << i)) w.cta_indices.push_back(i);
348	      }
349	    }
350	
351	    if (req.desc_slot >= VX_DCR_DXA_DESC_COUNT) {
352	      // Invalid descriptor — release barrier(s) directly without any LMEM write.
353	      release_all_barriers(w);
354	      finish_worker(w);
355	      return;
356	    }
357	
358	    w.desc = descriptors_.at(req.desc_slot);
359	    w.smem_stride = w.desc.smem_stride;
360	
361	    enumerate_work_list(w);
362	    if (w.work_list.empty()) {
363	      // No work — same edge case as above.
364	      release_all_barriers(w);
365	      finish_worker(w);
366	      return;
367	    }
368	
369	    // Mark the *last* work item — its multicast replay's last write carries
370	    // notify_done.
371	    w.work_list.back().last = true;
372	
373	    w.state = WState::RUNNING;
374	    perf_stats_.gmem_reads += w.work_list.size();
375	
376	    DT(3, simobject_->name() << "[" << w.worker_id << "] start: core="
377	       << req.core->id() << ", wid=" << req.wid
378	       << ", slot=" << req.desc_slot
379	       << ", lines=" << w.work_list.size()
380	       << ", multicast=" << w.is_multicast
381	       << ", num_ctas=" << w.cta_indices.size());
382	  }
383	
384	  // Enumerate (CL, smem-word, byte-offset, length, oob) tuples — one per
385	  // GMEM CL the transfer needs to read. Row-major iteration over outer
386	  // dims, contiguous span over dim-0, dedup of consecutive same-CL.
387	  void enumerate_work_list(Worker& w) {
388	    const auto& desc = w.desc;
389	    uint32_t rank = desc_rank(desc.meta);
390	    if (rank < 1 || rank > 5) return;
391	
392	    uint32_t   elem_bytes  = desc_elem_bytes(desc.meta);
393	    DestLayout layout      = desc_layout(desc.meta);
394	    bool       dest_kmajor = (layout == DestLayout::KMajor);
395	    bool       dest_tiled  = desc_dest_tiled(desc.meta);
396	    std::array<uint32_t, 5> tiles = {};
397	    for (uint32_t d = 0; d < 5; ++d)
398	      tiles[d] = (d < rank) ? std::max<uint32_t>(1u, desc.tile_sizes[d]) : 1u;
399	
400	    // K-major / tiled (Flat, BlockMajor) scatter require rank ≤ 2.
401	    if ((dest_kmajor || dest_tiled) && rank > 2) {
402	      dest_kmajor = false;
403	      dest_tiled  = false;
404	      layout      = DestLayout::RowMajor;
405	    }
406	    // Both share the single-element scatter datapath (one read → per-element
407	    // strided/permuted writes); row-major writes the span contiguously.
408	    bool scatter = dest_kmajor || dest_tiled;
409	
410	    uint32_t total_rows = 1;
411	    for (uint32_t d = 1; d < rank; ++d) total_rows *= tiles[d];
412	    uint32_t row_elems = tiles[0];
413	
414	    // K-major SMEM per-lane stride = tile1 * elem_bytes.
415	    uint32_t per_lane_stride_bytes = tiles[1] * elem_bytes;
416	
417	    // Tiled (Flat/BlockMajor) geometry: ratio = 32-bit-word / elem, tcN from
418	    // ESTRIDE2, n_steps = row_elems(=xtileN) / tcN.
419	    uint32_t geo_ratio  = dest_tiled ? std::max<uint32_t>(1u, 4u / elem_bytes) : 1u;
420	    uint32_t geo_tcN    = dest_tiled ? desc_geo_tcn(desc) : 1u;
421	    uint32_t geo_nsteps = dest_tiled ? std::max<uint32_t>(1u, row_elems / geo_tcN) : 1u;
422	
423	    uint32_t cfill = desc.cfill;
424	    uint64_t global_prev_cl = ~uint64_t(0);
425	
426	    for (uint32_t row = 0; row < total_rows; ++row) {
427	      // Decompose row into outer-dim local offsets (dim1 varies fastest).
428	      uint32_t outer[4] = {};
429	      uint32_t rem = row;
430	      for (uint32_t d = 1; d < rank; ++d) {
431	        outer[d - 1] = rem % tiles[d];
432	        rem /= tiles[d];
433	      }
434	
435	      // OOB check on outer dims.
436	      bool row_in_bounds = true;
437	      for (uint32_t d = 1; d < rank; ++d) {
438	        if (w.req.coords[d] + outer[d - 1] >= desc.sizes[d]) { row_in_bounds = false; break; }
439	      }
440	
441	      // First element GMEM addr in this row.
442	      uint64_t row_gbase = desc.base_addr + uint64_t(w.req.coords[0]) * elem_bytes;
443	      for (uint32_t d = 1; d < rank; ++d)
444	        row_gbase += uint64_t(w.req.coords[d] + outer[d - 1]) * uint64_t(desc.strides[d - 1]);
445	
446	      // SMEM destination base for this row:
447	      //   Row-major:  base + row_idx * row_elems * elem_bytes  (i1 outer × i0 inner).
448	      //   K-major:    base + outer[0] * elem_bytes              (lane stride applies per e0 below).
449	      //   Tiled:      computed per-element below (smem_wr recomputes the permuted dest).
450	      uint64_t row_smem_base = dest_kmajor
451	          ? (w.req.smem_addr + uint64_t(outer[0]) * elem_bytes)
452	          : (w.req.smem_addr + uint64_t(row * row_elems) * elem_bytes);
453	
454	      // Walk dim-0 elements; each LineWork carries one MemReq write of at
455	      // most one LMEM word AND at most one GMEM CL (so byteen fits in the
456	      // 64-byte mem_block payload). K-major scatters each element to its
457	      // own SMEM destination (lane stride = tile1 * elem_bytes).
458	      for (uint32_t e0 = 0; e0 < row_elems; ) {
459	        uint64_t gaddr_e = row_gbase + uint64_t(e0) * elem_bytes;
460	        uint64_t saddr_e;
461	        if (dest_tiled) {
462	          uint32_t de = tiled_dest_elem(layout, outer[0], e0, geo_ratio, geo_tcN, geo_nsteps);
463	          saddr_e = w.req.smem_addr + uint64_t(de) * elem_bytes;
464	        } else if (dest_kmajor) {
465	          saddr_e = row_smem_base + uint64_t(e0) * uint64_t(per_lane_stride_bytes);
466	        } else {
467	          saddr_e = row_smem_base + uint64_t(e0) * elem_bytes;
468	        }
469	        uint64_t cl_addr = gaddr_e & kGmemLineMask;
470	        uint64_t sword   = saddr_e & ~uint64_t(kLmemWordSize - 1);
471	        uint32_t cl_off  = uint32_t(gaddr_e - cl_addr);
472	        uint32_t s_off   = uint32_t(saddr_e - sword);
473	        uint32_t cl_room  = kGmemLineSize - cl_off;
474	        uint32_t sw_room  = kLmemWordSize - s_off;
475	        uint32_t row_room = (row_elems - e0) * elem_bytes;
476	        // The GMEM read span is ALWAYS coalesced to the cache line: dim-0
477	        // elements are contiguous in global memory, so one cache-line read
478	        // covers as many as fit. K-major then SCATTERS those elements to
479	        // strided SMEM destinations (one read → km_num_elems writes); row-major
480	        // writes them contiguously (bounded by the SMEM word). This mirrors the
481	        // RTL addr_gen, which reads per cache line and never re-reads per element.
482	        uint32_t gspan = scatter
483	            ? std::min({cl_room, row_room, uint32_t(VX_CFG_MEM_BLOCK_SIZE)})
484	            : std::min({cl_room, sw_room, row_room, uint32_t(VX_CFG_MEM_BLOCK_SIZE)});
485	        // Round to a whole-element multiple — ensures e0 advances by an
486	        // integer count and avoids off-by-one element splits.
487	        gspan -= gspan % elem_bytes;
488	        if (gspan == 0) break;
489	        uint32_t num_elems = gspan / elem_bytes;
490	
491	        bool elem_oob = !row_in_bounds || (w.req.coords[0] + e0 >= desc.sizes[0]);
492	        // OOB is determined per-element at the start of the span; tile widths
493	        // are typically aligned to dim-0 size, so this is exact for the common case.
494	
495	        LineWork lw{};
496	        lw.gmem_cl_addr     = cl_addr;
497	        lw.smem_word_addr   = sword;
498	        lw.cl_byte_offset   = cl_off;
499	        lw.smem_byte_offset = s_off;
500	        // Row-major: one contiguous write of the whole span. Scatter (K-major
501	        // or tiled Flat/BlockMajor): each element is its own write (elem_bytes),
502	        // gathered into block writes by smem_wr.
503	        lw.valid_length     = scatter ? elem_bytes : gspan;
504	        lw.cfill            = cfill;
505	        lw.oob              = elem_oob;
506	        lw.last             = false;
507	        lw.km_num_elems     = scatter ? num_elems : 1;
508	        lw.km_lane_stride   = dest_kmajor ? per_lane_stride_bytes : 0;
509	        lw.dest_layout      = uint8_t(layout);
510	        lw.tile_k_row       = outer[0];   // tiled scatter: K-row (dim1)
511	        lw.tile_n_base      = e0;          // tiled scatter: N (dim0) span start
512	
513	        // Dedup consecutive same-CL (non-OOB only).
514	        if (!elem_oob && cl_addr == global_prev_cl) {
515	          ++perf_stats_.gmem_dedup;
516	        } else if (!elem_oob) {
517	          global_prev_cl = cl_addr;
518	        }
519	        w.work_list.push_back(lw);
520	
521	        e0 += num_elems;
522	      }
523	    }
524	  }
525	
526	  // ── gmem_req: issue MemReqs with available inflight slots ────────────
527	  void tick_worker_gmem_req(Worker& w) {
528	    // One AGU step per cycle: advance ag_idx by at most one, issuing at most
529	    // one GMEM read to this worker's ReqIn port (or one OOB skip). A while-loop
530	    // here would issue many reads to a single port in one cycle.
531	    if (w.ag_idx >= w.work_list.size())
532	      return;
533	
534	    // Find a free slot.
535	    uint32_t slot = UINT32_MAX;
536	    for (uint32_t s = 0; s < w.inflight.size(); ++s) {
537	      if (!w.inflight[s].allocated) { slot = s; break; }
538	    }
539	    if (slot == UINT32_MAX) return; // all slots in flight
540	
541	    const LineWork& lw = w.work_list[w.ag_idx];
542	
543	    // OOB lines skip the GMEM request entirely; we synthesize an immediate
544	    // arrival (rsp data left null — smem_wr will use cfill).
545	    if (lw.oob) {
546	      w.inflight[slot].allocated   = true;
547	      w.inflight[slot].rsp_arrived = true;
548	      w.inflight[slot].rsp_data.reset();
549	      w.inflight[slot].work        = lw;
550	      w.issued_order.push_back(slot);
551	      ++w.ag_idx;
552	      return;
553	    }
554	
555	    // Issue real GMEM read. Tag = per-worker slot id (gmem_arb_ prepends
556	    // its own input-index bits for response routing — we only see slot
557	    // bits coming back).
558	    MemReq mreq;
559	    mreq.addr  = lw.gmem_cl_addr;
560	    mreq.tag   = slot;
561	    mreq.hart_id   = w.req.core->id();
562	    mreq.uuid  = w.req.uuid;
563	
564	    auto& ch = gmem_arb_->ReqIn.at(w.worker_id);
565	    if (!ch.try_send(mreq)) return; // arb backpressure
566	
567	    w.inflight[slot].allocated   = true;
568	    w.inflight[slot].rsp_arrived = false;
569	    w.inflight[slot].rsp_data.reset();
570	    w.inflight[slot].work        = lw;
571	    w.issued_order.push_back(slot);
572	    ++w.ag_idx;
573	  }
574	
575	  // ── smem_wr: drain ready slots, build LMEM MemReqs ───────────────────
576	  //
577	  // In-order: consume issued_order.front(); stall on the head until its
578	  // GMEM response has arrived.
579	  void tick_worker_smem_wr(Worker& w) {
580	    if (w.issued_order.empty()) {
581	      // Nothing in flight — if all addr_gen done, transfer is finished.
582	      if (w.ag_idx == w.work_list.size()) finish_worker(w);
583	      return;
584	    }
585	
586	    uint32_t slot = w.issued_order.front();
587	    auto& s = w.inflight[slot];
588	    if (!s.rsp_arrived) return; // wait
589	
590	    // Determine destination core's LMEM port.
591	    uint32_t cluster_local_cid = w.req.core->id() % kCoresPerCluster;
592	    auto& lmem_ch = simobject_->lmem_req_out.at(cluster_local_cid);
593	    if (lmem_ch.full()) return; // backpressure
594	
595	    const LineWork& lw = s.work;
596	
597	    // One cache-line read fans out to its scattered writes. The K-major
598	    // elements landing in the same SMEM block are written TOGETHER in one
599	    // byte-masked block write: the per-core LMEM port accepts a full
600	    // VX_CFG_MEM_BLOCK_SIZE word per cycle (banked), exactly like the warp
601	    // array's transpose — so the engine drains at SMEM bandwidth, not one
602	    // element per cycle (TMA-style full-bandwidth scatter). Cursors:
603	    // km_elem_idx advances one block per beat; mc_cta_idx replays the whole
604	    // group to each multicast receiver.
605	    const uint32_t num_elems = lw.km_num_elems ? lw.km_num_elems : 1;
606	    const uint32_t e0        = w.km_elem_idx;
607	    const uint32_t wlen      = lw.valid_length;
608	
609	    uint32_t cta_warp_idx = 0;
610	    uint64_t cta_off = 0;
611	    if (w.is_multicast) {
612	      cta_warp_idx = w.cta_indices.at(w.mc_cta_idx);
613	      cta_off = uint64_t(cta_warp_idx) * w.smem_stride;
614	    }
615	
616	    // Per-element SMEM byte destination. K-major: uniform lane stride from a
617	    // span base. Tiled (Flat/BlockMajor): permuted index from the WGMMA
618	    // B-buffer layout formula (idx = within-span dim-0 offset → N = base+idx).
619	    const bool     tiled    = desc_dest_tiled(w.desc.meta);
620	    const uint32_t t_eb     = desc_elem_bytes(w.desc.meta);
621	    const uint32_t t_ratio  = tiled ? std::max<uint32_t>(1u, 4u / t_eb) : 1u;
622	    const uint32_t t_tcN    = tiled ? desc_geo_tcn(w.desc) : 1u;
623	    const uint32_t t_nsteps = tiled ? std::max<uint32_t>(1u, uint32_t(w.desc.tile_sizes[0]) / t_tcN) : 1u;
624	    auto dest_byte_of = [&](uint32_t idx) -> uint64_t {
625	      if (tiled) {
626	        uint32_t de = tiled_dest_elem(DestLayout(lw.dest_layout), lw.tile_k_row,
627	                                      lw.tile_n_base + idx, t_ratio, t_tcN, t_nsteps);
628	        return w.req.smem_addr + uint64_t(de) * t_eb + cta_off;
629	      }
630	      return lw.smem_word_addr + lw.smem_byte_offset
631	           + uint64_t(idx) * lw.km_lane_stride + cta_off;
632	    };
633	
634	    // The block targeted this beat = the block of scatter element e0.
635	    uint64_t base_byte0 = dest_byte_of(e0);
636	    uint64_t dword = base_byte0 & ~uint64_t(kLmemWordSize - 1);
637	
638	    // Build LMEM MemReq with TLM payload.
639	    MemReq req;
640	    req.addr   = dword;
641	    req.op = MemOp::ST;
642	    req.tag    = w.req.core->id();           // routing tag
643	    req.hart_id = w.req.core->id();
644	    req.uuid   = w.req.uuid;
645	    uint64_t byteen = 0;
646	    auto blk = make_mem_block();
647	    const uint32_t pat = lw.cfill;
648	
649	    // Gather every scatter element that falls in this block into one write.
650	    uint32_t ee = e0;
651	    for (; ee < num_elems; ++ee) {
652	      uint64_t dest_byte = dest_byte_of(ee);
653	      if ((dest_byte & ~uint64_t(kLmemWordSize - 1)) != dword) break;
654	      uint32_t doff  = uint32_t(dest_byte - dword);
655	      uint64_t emask = (wlen >= 64) ? ~uint64_t(0) : ((uint64_t(1) << wlen) - 1ull);
656	      byteen |= emask << doff;
657	      if (s.rsp_data) {
658	        std::memcpy(blk->data() + doff,
659	                    s.rsp_data->data() + lw.cl_byte_offset + ee * wlen,
660	                    wlen);
661	      } else {
662	        for (uint32_t b = 0; b < wlen; ++b)
663	          (*blk)[doff + b] = uint8_t((pat >> ((b & 3) * 8)) & 0xff);
664	      }
665	    }
666	    req.byteen = byteen;
667	    req.data = blk;
668	
669	    // notify_done on the LAST block write of the transfer — when the gather
670	    // reached the last scatter element of the last work item, per receiver.
671	    bool is_last_elem   = (ee == num_elems);
672	    bool is_last_work   = lw.last;
673	    bool is_last_replay = !w.is_multicast || (w.mc_cta_idx + 1 == w.cta_indices.size());
674	    if (is_last_work && is_last_elem && (w.is_multicast || is_last_replay)) {
675	      req.flags.dxa_notify_done   = 1;
676	      req.flags.dxa_notify_bar_id = w.req.bar_id + (w.is_multicast ? cta_warp_idx : 0u);
677	    }
678	
679	    lmem_ch.send(req);
680	    ++w.writes_emitted;
681	    ++perf_stats_.lmem_writes;
682	
683	    // Advance scatter cursor (to first ungathered element); then multicast
684	    // cursor; then release the slot.
685	    if (!is_last_elem) {
686	      w.km_elem_idx = ee;
687	    } else {
688	      w.km_elem_idx = 0;
689	      if (w.is_multicast && (w.mc_cta_idx + 1) < w.cta_indices.size()) {
690	        ++w.mc_cta_idx;
691	      } else {
692	        w.mc_cta_idx = 0;
693	        // Slot done — release.
694	        s.allocated = false;
695	        s.rsp_arrived = false;
696	        s.rsp_data.reset();
697	        w.issued_order.pop_front();
698	      }
699	    }
700	  }
701	
702	  void release_all_barriers(Worker& w) {
703	    // bar_id is RAW (encoded); decode at release call site.
704	    if (w.is_multicast) {
705	      for (uint32_t cta : w.cta_indices) {
706	        uint32_t decoded = bar_decode_id(w.req.bar_id + cta, VX_CFG_NUM_BARRIERS);
707	        w.req.core->barrier_event_release(decoded);
708	      }
709	    } else {
710	      uint32_t decoded = bar_decode_id(w.req.bar_id, VX_CFG_NUM_BARRIERS);
711	      w.req.core->barrier_event_release(decoded);
712	    }
713	  }
714	
715	  void finish_worker(Worker& w) {
716	    if (w.state == WState::RUNNING || w.state == WState::IDLE) {
717	      uint64_t latency = cycle_ - w.issue_cycle;
718	      ++perf_stats_.transfers;
719	      perf_stats_.total_latency += latency;
720	      DT(3, simobject_->name() << "[" << w.worker_id << "] complete: core="
721	         << w.req.core->id() << ", bar=" << w.req.bar_id
722	         << ", writes=" << w.writes_emitted << ", latency=" << latency);
723	    }
724	    w.state = WState::IDLE;
725	    w.work_list.clear();
726	    w.cta_indices.clear();
727	    w.issued_order.clear();
728	    w.ag_idx = 0;
729	    w.mc_cta_idx = 0;
730	    w.km_elem_idx = 0;
731	    w.writes_emitted = 0;
732	  }
733	
734	  // ── Members ──────────────────────────────────────────────────────────
735	  DxaCore*    simobject_;
736	  MemArbiter* gmem_arb_;
737	  std::array<Descriptor, VX_DCR_DXA_DESC_COUNT> descriptors_;
738	  std::deque<DxaReq>     queue_;
739	  std::vector<Worker>    workers_;
740	  uint32_t               rr_req_ = 0;
741	  uint64_t               cycle_;
742	  DxaCore::PerfStats     perf_stats_;
743	};
744	
745	// ════════════════════════════════════════════════════════════════════
746	// DxaCore — wrappers
747	// ════════════════════════════════════════════════════════════════════
748	
749	DxaCore::DxaCore(const SimContext& ctx, const char* name, Cluster* cluster)
750	  : SimObject<DxaCore>(ctx, name)
751	  , dxa_req_in(kCoresPerCluster, this)
752	  , gmem_req_out(kDxaMemPorts, this)
753	  , gmem_rsp_in(kDxaMemPorts, this)
754	  , lmem_req_out(kCoresPerCluster, this)
755	{
756	  __unused(cluster);
757	
758	  // Build the GMEM arbiter (VX_CFG_NUM_DXA_CORES workers → kDxaMemPorts L2-facing).
759	  // Tag layout used by workers: high bit packs worker_id, low bits the
760	  // per-worker inflight slot. We pass TAG_SEL_IDX so the arb can route
761	  // responses back to the right input.
762	  char sname[100];
763	  snprintf(sname, 100, "%s-gmem-arb", name);
764	  gmem_arb_ = MemArbiter::Create(sname, ArbiterType::RoundRobin, VX_CFG_NUM_DXA_CORES, kDxaMemPorts);
765	  for (uint32_t i = 0; i < kDxaMemPorts; ++i) {
766	    gmem_arb_->ReqOut.at(i).bind(&gmem_req_out.at(i));
767	    gmem_rsp_in.at(i).bind(&gmem_arb_->RspIn.at(i));
768	  }
769	
770	  impl_ = new Impl(this, gmem_arb_.get());
771	}
772	
773	DxaCore::~DxaCore() {
774	  delete impl_;
775	}
776	
777	void DxaCore::on_reset() { impl_->reset(); }
778	void DxaCore::on_tick()  { impl_->tick(); }
779	
780	int DxaCore::dcr_write(uint32_t addr, uint32_t value) {
781	  return impl_->dcr_write(addr, value);
782	}
783	
784	const DxaCore::PerfStats& DxaCore::perf_stats() const {
785	  return impl_->perf_stats();
786	}
