1	// Host driver for dxa_copy_mcast — intra-core multicast.
2	//
3	// num_recv = VX_CFG_NUM_WARPS single-warp CTAs co-resident on one core, each
4	// receiving the same tile via DXA multicast.
5	
6	#include <cstdlib>
7	#include <iostream>
8	#include <unistd.h>
9	#include <vector>
10	
11	#include <VX_types.h>
12	#include <vortex.h>
13	#include <dxa.h>
14	
15	#include "common.h"
16	
17	#define RT_CHECK(_expr)                                         \
18	  do {                                                          \
19	    int _ret = _expr;                                           \
20	    if (0 == _ret) break;                                       \
21	    printf("Error: '%s' returned %d!\n", #_expr, (int)_ret);   \
22	    cleanup();                                                  \
23	    exit(-1);                                                   \
24	  } while (false)
25	
26	static const char* kernel_file = "kernel.vxbin";
27	static uint32_t    tile_rows   = 16;
28	static uint32_t    tile_cols   = 4;
29	static uint32_t    src_rows    = 16;
30	static uint32_t    src_cols    = 16;
31	
32	static vx_device_h device     = nullptr;
33	static vx_buffer_h src_buffer = nullptr;
34	static vx_buffer_h dst_buffer = nullptr;
35	static vx_queue_h  queue      = nullptr;
36	static vx_module_h module_    = nullptr;
37	static vx_kernel_h kernel     = nullptr;
38	static kernel_arg_t kernel_arg = {};
39	
40	static void show_usage() {
41	  std::cout << "Usage: [-k kernel] [-r src_rows] [-c src_cols] "
42	               "[-R tile_rows] [-C tile_cols] [-h]\n";
43	}
44	
45	static void parse_args(int argc, char** argv) {
46	  int c;
47	  while ((c = getopt(argc, argv, "r:c:R:C:k:h")) != -1) {
48	    switch (c) {
49	      case 'r': src_rows  = atoi(optarg); break;
50	      case 'c': src_cols  = atoi(optarg); break;
51	      case 'R': tile_rows = atoi(optarg); break;
52	      case 'C': tile_cols = atoi(optarg); break;
53	      case 'k': kernel_file = optarg; break;
54	      case 'h': show_usage(); exit(0);
55	      default:  show_usage(); exit(-1);
56	    }
57	  }
58	}
59	
60	void cleanup() {
61	  if (device) {
62	    if (src_buffer) vx_buffer_release(src_buffer);
63	    if (dst_buffer) vx_buffer_release(dst_buffer);
64	    if (kernel)  vx_kernel_release(kernel);
65	    if (module_) vx_module_release(module_);
66	    if (queue)   vx_queue_release(queue);
67	    vx_device_dump_perf(device, stdout);
68	    vx_device_release(device);
69	  }
70	}
71	
72	int main(int argc, char* argv[]) {
73	  parse_args(argc, argv);
74	  std::srand(42);
75	
76	  RT_CHECK(vx_device_open(0, &device));
77	
78	  vx_queue_info_t qi = { sizeof(qi), nullptr, VX_QUEUE_PRIORITY_NORMAL, 0 };
79	  RT_CHECK(vx_queue_create(device, &qi, &queue));
80	
81	  // Single-warp CTAs: block = (tile_cols, 1) so each CTA uses exactly one
82	  // warp. num_recv = VX_CFG_NUM_WARPS so all receivers fit co-resident on one core.
83	  uint64_t num_warps = 0, num_threads = 0;
84	  RT_CHECK(vx_device_query(device, VX_CAPS_NUM_WARPS, &num_warps));
85	  RT_CHECK(vx_device_query(device, VX_CAPS_NUM_THREADS, &num_threads));
86	
87	  if (tile_cols != (uint32_t)num_threads) {
88	    std::cout << "Error: tile_cols (" << tile_cols
89	              << ") must equal VX_CFG_NUM_THREADS (" << num_threads
90	              << ") for single-warp CTAs\n";
91	    cleanup();
92	    return -1;
93	  }
94	
95	  const uint32_t num_recv   = (uint32_t)num_warps;
96	  const uint32_t tile_elems = tile_rows * tile_cols;
97	  const uint32_t local_mem  = tile_elems * sizeof(TYPE);
98	  const uint32_t src_elems  = src_rows * src_cols;
99	  const uint32_t src_bytes  = src_elems * sizeof(TYPE);
100	  const uint32_t dst_bytes  = num_recv * tile_elems * sizeof(TYPE);
101	
102	  std::cout << "dxa_copy_mcast (intra-core multicast)\n";
103	  std::cout << "  source: " << src_rows << " x " << src_cols
104	            << ", tile: " << tile_rows << " x " << tile_cols << "\n";
105	  std::cout << "  block=" << tile_cols << "x1 (single warp), grid="
106	            << num_recv << "x1, num_recv=" << num_recv << "\n";
107	  std::cout << "  local_mem=" << local_mem << " bytes\n";
108	
109	  RT_CHECK(vx_check_occupancy(device, tile_cols, local_mem));
110	
111	  RT_CHECK(vx_buffer_create(device, src_bytes, VX_MEM_READ,  &src_buffer));
112	  RT_CHECK(vx_buffer_address(src_buffer, &kernel_arg.src_addr));
113	  RT_CHECK(vx_buffer_create(device, dst_bytes, VX_MEM_WRITE, &dst_buffer));
114	  RT_CHECK(vx_buffer_address(dst_buffer, &kernel_arg.dst_addr));
115	
116	  // Distinctive source pattern (linear index + 1).
117	  std::vector<TYPE> h_src(src_elems);
118	  for (uint32_t i = 0; i < src_elems; ++i)
119	    h_src[i] = static_cast<TYPE>(i + 1);
120	  RT_CHECK(vx_enqueue_write(queue, src_buffer, 0, h_src.data(), src_bytes, 0, nullptr, nullptr));
121	
122	  // Program DXA descriptor for the tile.
123	  constexpr uint32_t kDescSrc = 0;
124	  RT_CHECK(vortex::dxa::program_2d(device, kDescSrc, kernel_arg.src_addr,
125	    /*size0=*/src_cols, /*size1=*/src_rows,
126	    /*stride0_bytes=*/src_cols * sizeof(TYPE),
127	    /*tile0=*/tile_cols, /*tile1=*/tile_rows,
128	    /*elem_bytes=*/sizeof(TYPE)));
129	  // Multicast stride = local_mem (per-CTA SMEM size). Dispatcher allocates
130	  // sequential LMEM regions so receiver k's region starts at k*local_mem.
131	  RT_CHECK(vortex::dxa::set_multicast(device, kDescSrc, local_mem));
132	
133	  kernel_arg.tile_rows      = tile_rows;
134	  kernel_arg.tile_cols      = tile_cols;
135	  kernel_arg.src_row_stride = src_cols;
136	  kernel_arg.num_recv       = num_recv;
137	
138	  uint32_t grid_dim[2]  = { num_recv, 1 };
139	  uint32_t block_dim[2] = { tile_cols, 1 };
140	
141	  RT_CHECK(vx_module_load_file(device, kernel_file, &module_));
142	  RT_CHECK(vx_module_get_kernel(module_, "main", &kernel));
143	
144	  // Host result buffer — must outlive the async read enqueued below.
145	  std::vector<TYPE> h_dst(num_recv * tile_elems, 0);
146	
147	  std::cout << "start\n";
148	  vx_event_h launch_ev = nullptr;
149	  {
150	    vx_launch_info_t li = {};
151	    li.struct_size  = sizeof(li);
152	    li.kernel       = kernel;
153	    li.args_host    = &kernel_arg;
154	    li.args_size    = sizeof(kernel_arg);
155	    li.ndim         = 2;
156	    li.grid_dim[0]  = grid_dim[0];
157	    li.grid_dim[1]  = grid_dim[1];
158	    li.block_dim[0] = block_dim[0];
159	    li.block_dim[1] = block_dim[1];
160	    li.lmem_size    = local_mem;
161	    // Multicast group: all num_recv receiver CTAs share one B tile and must be
162	    // co-resident on one core in contiguous CTA slots. The grid is num_recv×1,
163	    // so the group spans the X axis. Without this, cluster_size defaults to 1,
164	    // get_cluster_rank() is 0 for every CTA, and every CTA (not just rank-0)
165	    // fires the multicast — over-releasing receivers' event barriers and
166	    // walking the barrier-id space past its bounds.
167	    li.cluster_dim[0] = num_recv;
168	    li.cluster_dim[1] = 1;
169	    RT_CHECK(vx_enqueue_launch(queue, &li, 0, nullptr, &launch_ev));
170	  }
171	
172	  // Verify each receiver got the same tile.
173	  vx_event_h read_ev = nullptr;
