// Decode a packed kernel bar_id (local_group_id | (bar_no << 8)) to a flat barrier index.
// Preserves the global barrier flag (bit 31).
inline uint32_t bar_decode_id(uint32_t bar_id_raw, uint32_t num_barriers) {
